document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("btn-clear-data"),t=document.getElementById("status-msg");e&&e.addEventListener("click",async()=>{try{await chrome.storage.local.remove("dailyStats"),t&&(t.textContent="Data successfully cleared. Starting fresh!",t.style.color="#03dac6",setTimeout(()=>{t.textContent=""},3e3))}catch(a){console.error("Failed to clear data:",a),t&&(t.textContent="Error clearing data. Check console.",t.style.color="#cf6679")}})});
